<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;class Child extends Model{protected $fillable=['parent_id','name','dob','gender','blood_group','guardian_phone','address'];protected $casts=['dob'=>'date'];public function parent(){return $this->belongsTo(User::class,'parent_id');}public function vaccinations(){return $this->hasMany(VaccinationRecord::class);}public function appointments(){return $this->hasMany(Appointment::class);}}
